/** Only same-origin adapters may receive an address, code or WebAuthn proof. */
export function signInEndpoint(path: string): string {
	if (!path.startsWith('/') || path.startsWith('//') || /[\\\u0000-\u0020]/.test(path)) {
		throw new Error('Sign-in requires a same-origin endpoint.')
	}
	return path
}

export async function signInRequest<T>(
	path: string,
	body: object,
	signal?: AbortSignal,
): Promise<T> {
	const response = await fetch(signInEndpoint(path), {
		method: 'POST',
		credentials: 'same-origin',
		headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
		body: JSON.stringify(body),
		signal,
		redirect: 'error',
	})
	const data = await response.json().catch(() => null)
	if (!response.ok) {
		const raw = response.headers.get('Retry-After')
		const seconds =
			raw && /^\d+$/.test(raw)
				? Number(raw)
				: raw
					? Math.ceil((Date.parse(raw) - Date.now()) / 1000)
					: 0
		throw new SignInRequestError(
			response.status === 401 && data?.error === 'mfa_required'
				? 'Enter the code from your authenticator, or use a recovery code.'
				: response.status === 429
					? 'Too many attempts. Wait a moment and try again.'
					: response.status >= 500
						? 'Sign-in is unavailable right now. Please try again.'
						: 'That was not accepted. Try again, or request a new code if it expired.',
			response.status === 429 ? Math.max(1, Number.isFinite(seconds) ? seconds || 30 : 30) : 0,
			response.status === 401 && data?.error === 'mfa_required' ? 'mfa_required' : undefined,
		)
	}
	if (!data || typeof data !== 'object')
		throw new Error('Sign-in could not complete. Please try again.')
	return data as T
}

export function maskSignInEmail(email: string): string {
	const at = email.lastIndexOf('@')
	return at > 0 ? `${email[0]}•••${email.slice(at)}` : email
}

export function codeDigits(value: string): string {
	return value
		.replace(/[\s-]/g, '')
		.replace(/[^0-9]/g, '')
		.slice(0, 6)
}

/** Audience order is retained after the platform's primary provider. */
export function visibleSignInProviders<T extends { id: string }>(
	providers: readonly T[],
	userAgent: string,
): T[] {
	const embedded = /FBAN|FBAV|Instagram|Line\/|; wv\)|\bwv\b/i.test(userAgent)
	const primary = /iPhone|iPad|iPod/.test(userAgent) ? 'apple' : 'google'
	return providers
		.filter((provider) => !(embedded && provider.id === 'google'))
		.map((provider, index) => ({ provider, rank: provider.id === primary ? -1 : index }))
		.sort((a, b) => a.rank - b.rank)
		.map(({ provider }) => provider)
}
